560	    pub(crate) static REQUESTS: std::sync::Arc<std::sync::atomic::AtomicU64>;
561	}
562	
563	/// One checker session bound to a snapshot and project.
564	pub(crate) struct Rpc {
565	    client: Client,
566	    deadline: Duration,
567	    snapshot: u64,
568	    project: String,
569	    /// The compiler options the program was built with, for a snapshot that adds files to it ([`Rpc::layered`]).
570	    options: Value,
571	    /// Every call and its answer, when the caller asked to record a replay fixture; shared with a layered snapshot.
572	    recording: Option<Arc<Mutex<Vec<Value>>>>,
573	    calls: Arc<Mutex<BTreeMap<&'static str, u64>>>,
574	    /// The snapshots of the other lanes [`Rpc::open_programs`] opened beside this one, which [`Rpc::release`] on this
575	    /// one releases too, unless [`Rpc::release_lanes`] released them already.
576	    others: Mutex<Vec<u64>>,
577	}
578	
579	/// A diagnostic the checker reports for a file: where it starts and what it says.
580	#[derive(Debug, Clone, Deserialize)]
581	#[serde(rename_all = "camelCase")]
582	pub(crate) struct FileDiagnostic {
583	    /// The file the error is in, which is not always the file asked about.
584	    pub file_name: String,
585	    pub start_position: Position,
586	    /// `DiagnosticCategory`: warning 0, error 1, suggestion 2, message 3.
587	    pub category: u8,
588	    /// The message; a chain of messages arrives as an object, of which only the first is shown.
589	    pub text: Value,
590	}
591	
592	impl FileDiagnostic {
593	    pub(crate) fn is_error(&self) -> bool {
594	        self.category == 1
595	    }
596	
597	    pub(crate) fn message(&self) -> String {
598	        match &self.text {
599	            Value::String(text) => text.clone(),
600	            other => other.get("messageText").and_then(Value::as_str).unwrap_or("a type error").to_string(),
601	        }
602	    }
603	}
604	
605	/// A position in a file, zero-based.
606	#[derive(Debug, Clone, Copy, Deserialize)]
607	pub(crate) struct Position {
608	    pub line: usize,
609	}
610	
611	impl Rpc {
612	    /// Initializes the `tsc` session and reads the compiler options, once per process. The beta panics on
613	    /// string-valued enum options such as `target: "es2022"`, so options come from `parseConfigFile`, which yields
614	    /// numeric ones.
615	    pub(crate) async fn prepare(
616	        client: &Client,
617	        deadline: Duration,
618	        tsconfig: Option<&str>,
619	    ) -> Result<Value, CallError> {
620	        let rpc = Rpc {
621	            client: client.clone(),
622	            deadline,
623	            snapshot: 0,
624	            project: String::new(),
625	            options: Value::Null,
626	            recording: None,
627	            calls: Arc::default(),
628	            others: Mutex::default(),
629	        };
630	        rpc.call(&Initialize).await?;
631	        Ok(match tsconfig {
632	            Some(file) => {
633	                let parsed: Value = decode(&rpc.call(&ParseConfigFile { file }).await?)?;
634	                parsed.get("options").cloned().unwrap_or_else(default_options)
635	            }
636	            None => default_options(),
637	        })
638	    }
639	
640	    /// One snapshot of a program over `root_files` for each of `count` lanes (one when `count` is at most one), in a
641	    /// session it initializes first ([`Rpc::prepare`]), with one session bound to each, the `n`th asking down the
642	    /// checker's `n`th lane ([`Client::lane`]): a checker that answers requests about different snapshots at once
643	    /// ([`crate::checker`]) answers the sessions in parallel. Each lane has a snapshot of its own because the checker
644	    /// registers the symbols, types and signatures it hands out in one table per snapshot, behind one lock: two programs
645	    /// of one snapshot wait for each other on it. The first lane's snapshot is built from the disk; each other one is
646	    /// derived from it ([`Rpc::beside`]), so every program reads the same text of every file. They share the request
647	    /// counts and the recording; [`Rpc::release`] on the first releases every snapshot.
648	    pub(crate) async fn open_programs(
649	        client: Client,
650	        deadline: Duration,
651	        tsconfig: Option<&str>,
652	        root_files: &[String],
653	        record: bool,
654	        count: usize,
655	    ) -> Result<Vec<Rpc>, CallError> {
656	        let options = Rpc::prepare(&client, deadline, tsconfig).await?;
657	        let first = Rpc::open_with(client.lane(0), deadline, &options, root_files, record).await?;
658	        let mut lanes: Vec<Rpc> = Vec::with_capacity(count.max(1));
659	        for lane in 1..count {
660	            match first.beside(client.lane(lane), root_files).await {
661	                Ok(rpc) => lanes.push(rpc),
662	                Err(error) => {
663	                    // Nothing will hold the snapshots made so far to release them later.
664	                    first.release().await;
665	                    for opened in &lanes {
666	                        opened.release().await;
667	                    }
668	                    return Err(error);
669	                }
670	            }
671	        }
672	        let others = lanes.iter().map(|rpc| rpc.snapshot).collect();
673	        lanes.insert(0, Rpc { others: Mutex::new(others), ..first });
674	        Ok(lanes)
675	    }
676	
677	    /// A snapshot of its own for a program over `root_files` beside this one's, asked through `client`: derived from
678	    /// this snapshot (`updateSnapshot` with `createPrograms`), it reads every file as this one holds it, from the files
679	    /// this snapshot has read and parsed, and does not go to the disk again. It shares the request counts and the
680	    /// recording; it is released on its own.
681	    async fn beside(&self, client: Client, root_files: &[String]) -> Result<Rpc, CallError> {
682	        let changes = Changes {
683	            create_programs: Some([NewProgram { root_files, compiler_options: &self.options }]),
684	            ensure_programs: true,
685	            ..Changes::default()
686	        };
687	        let response: SnapshotResponse =
688	            decode(&self.call(&UpdateSnapshot { snapshot: self.snapshot, changes }).await?)?;
689	        let rpc = Rpc {
690	            client,
691	            deadline: self.deadline,
692	            snapshot: response.snapshot,
693	            project: String::new(),
694	            options: self.options.clone(),
695	            recording: self.recording.clone(),
696	            calls: self.calls.clone(),
697	            others: Mutex::default(),
698	        };
699	        // The response lists the programs the update made or changed: the one created, not this one's.
700	        let Some(project) = response.projects.into_iter().find(|project| project.id != self.project) else {
701	            // Nothing will hold this snapshot to release it later.
702	            rpc.release().await;
703	            return Err(CallError::Rejected("updateSnapshot created no program".to_string()));
704	        };
705	        Ok(Rpc { project: project.id, ..rpc })
706	    }
707	
708	    /// A snapshot over `root_files` in a session [`Rpc::prepare`] already initialized.
709	    pub(crate) async fn open_with(
710	        client: Client,
711	        deadline: Duration,
712	        options: &Value,
713	        root_files: &[String],
714	        record: bool,
715	    ) -> Result<Rpc, CallError> {
716	        let rpc = Rpc {
717	            client,
718	            deadline,
719	            snapshot: 0,
720	            project: String::new(),
721	            options: options.clone(),
722	            recording: record.then(Arc::default),
723	            calls: Arc::default(),
724	            others: Mutex::default(),
725	        };
726	        let program = NewProgram { root_files, compiler_options: options };
727	        rpc.created(Changes { create_programs: Some([program]), ..Changes::default() }).await
728	    }
729	
730	    /// A snapshot of a program rooted at `files` alone, held in the checker's memory and never written to disk (see
731	    /// [`Rpc::layered`]), in a session [`Rpc::prepare`] already initialized.
732	    pub(crate) async fn open_in_memory(
733	        client: Client,
734	        deadline: Duration,
735	        options: &Value,
736	        files: &[(String, String)],
737	    ) -> Result<Rpc, CallError> {
738	        let session = Rpc {
739	            client,
740	            deadline,
741	            snapshot: 0,
742	            project: String::new(),
743	            options: options.clone(),
744	            recording: None,
745	            calls: Arc::default(),
746	            others: Mutex::default(),
747	        };
748	        let roots: Vec<String> = files.iter().map(|(path, _)| path.clone()).collect();
749	        let program = NewProgram { root_files: &roots, compiler_options: options };
750	        let changes = Changes {
751	            file_system: Some(in_memory_layer(files)),
752	            create_programs: Some([program]),
753	            ..Changes::default()
754	        };
755	        session.created(changes).await
756	    }
757	
758	    /// The snapshot after this one with `files` added, held in the checker's memory and never written to disk (each is
759	    /// a root file, keyed by its absolute path), and this one's program rooted at `root_files` and them instead, built at
760	    /// once (`updateSnapshot` with `reconfigurePrograms`). It is derived from this snapshot, so it reads every other file
761	    /// as this one holds it, from the files this one has read and parsed, and holds one program: a fresh `createSnapshot`
762	    /// read and parsed every file again into a second whole program while this one's was still alive. The calls on it
763	    /// count, and are recorded, with this one's; it is released on its own, and this one stays alive until it is.
764	    pub(crate) async fn layered(&self, root_files: &[String], files: &[(String, String)]) -> Result<Rpc, CallError> {
765	        let mut roots = root_files.to_vec();
766	        roots.extend(files.iter().map(|(path, _)| path.clone()));
767	        let program = Reconfigured { id: &self.project, root_files: &roots, compiler_options: &self.options };
768	        let changes = Changes {
769	            file_system: Some(in_memory_layer(files)),
770	            reconfigure_programs: Some([program]),
771	            ensure_programs: true,
772	            ..Changes::default()
773	        };
774	        let response: SnapshotResponse =
775	            decode(&self.call(&UpdateSnapshot { snapshot: self.snapshot, changes }).await?)?;
776	        // The response lists the projects the update replaced: the reconfigured one, which may keep its id.
777	        let mut projects = response.projects.into_iter().map(|project| project.id);
778	        let project = match projects.len() {
779	            0 => self.project.clone(),
780	            1 => projects.next().unwrap_or_default(),
781	            _ => match projects.find(|id| *id == self.project) {
782	                Some(id) => id,
783	                None => {
784	                    // Nothing will hold this snapshot to release it later.
785	                    self.call(&Release { snapshot: response.snapshot }).await.ok();
786	                    return Err(CallError::Rejected(
787	                        "updateSnapshot changed programs other than the one reconfigured".to_string(),
788	                    ));
789	                }
790	            },
791	        };
792	        Ok(Rpc {
793	            client: self.client.clone(),
794	            deadline: self.deadline,
795	            snapshot: response.snapshot,
796	            project,
797	            options: self.options.clone(),
798	            recording: self.recording.clone(),
799	            calls: self.calls.clone(),
800	            others: Mutex::default(),
801	        })
802	    }
803	
804	    /// The snapshot after this one with `changed` and `deleted` read again from the disk and, given `roots`, its program
805	    /// rooted there instead, built at once (`updateSnapshot` with `ensurePrograms`). Files the program has not changed
806	    /// are kept as parsed: the checker re-reads only what it is told about, and a synthetic program sees even that
807	    /// only when it is rebuilt. The calls on it count with this one's; this snapshot stays alive until it is released.
808	    pub(crate) async fn updated(
809	        &self,
810	        changed: &[String],
811	        deleted: &[String],
812	        roots: Option<&[String]>,
813	    ) -> Result<Rpc, CallError> {
814	        let changes = Changes {
815	            file_notifications: (!changed.is_empty() || !deleted.is_empty())
816	                .then_some(FileNotifications { changed, deleted }),
817	            reconfigure_programs: roots
818	                .map(|root_files| [Reconfigured { id: &self.project, root_files, compiler_options: &self.options }]),
819	            ensure_programs: true,
820	            ..Changes::default()
821	        };
822	        let response: SnapshotResponse =
823	            decode(&self.call(&UpdateSnapshot { snapshot: self.snapshot, changes }).await?)?;
824	        // The response lists only the projects it replaced; the synthetic program keeps its id.
825	        let project = response.projects.into_iter().next().map_or_else(|| self.project.clone(), |project| project.id);
826	        Ok(Rpc {
827	            client: self.client.clone(),
828	            deadline: self.deadline,
829	            snapshot: response.snapshot,
830	            project,
831	            options: self.options.clone(),
832	            recording: self.recording.clone(),
833	            calls: self.calls.clone(),
834	            others: Mutex::default(),
835	        })
836	    }
837	
838	    /// Runs `work` on the checker thread this session asks ([`Client::run_on_thread`]), given this session as that
839	    /// thread asks it, in place; each request is bounded by this session's deadline.
840	    pub(crate) async fn run_on_thread<T: Send + 'static>(
841	        self: &Arc<Self>,
842	        work: impl FnOnce(Arc<Rpc>) -> T + Send + 'static,
843	    ) -> Result<T, CallError> {
844	        let this = Arc::clone(self);
845	        let run = self.client.run_on_thread(self.deadline, move |client| work(Arc::new(this.through(client))));
846	        run.await.map_err(classify)
847	    }
848	
849	    /// This session asked through `client`: the same snapshot and project, counts and recording.
850	    fn through(&self, client: Client) -> Rpc {
851	        Rpc {
852	            client,
853	            deadline: self.deadline,
854	            snapshot: self.snapshot,
855	            project: self.project.clone(),
856	            options: self.options.clone(),
857	            recording: self.recording.clone(),
858	            calls: self.calls.clone(),
859	            others: Mutex::default(),
860	        }
861	    }
862	
863	    /// The snapshot this session asks about.
864	    #[cfg(test)]
865	    pub(crate) fn snapshot_id(&self) -> u64 {
866	        self.snapshot
867	    }
868	
869	    /// Every file the snapshot's program read, as the checker names them.
870	    pub(crate) async fn source_file_names(&self) -> Result<Vec<String>, CallError> {
871	        self.scoped(Ask::SourceFileNames {}).await
872	    }
873	
874	    /// This session bound to the snapshot `createSnapshot` makes from `params`, and to its one project.
875	    async fn created(mut self, changes: Changes<'_>) -> Result<Rpc, CallError> {
876	        let response: SnapshotResponse = decode(&self.call(&CreateSnapshot(changes)).await?)?;
877	        self.snapshot = response.snapshot;
878	        let Some(project) = response.projects.into_iter().next() else {
879	            // Nothing will hold this snapshot to release it later.
880	            self.release().await;
881	            return Err(CallError::Rejected("createSnapshot returned no project".to_string()));
882	        };
883	        self.project = project.id;
884	        Ok(self)
885	    }
886	
887	    /// Releases the snapshot, and those of the lanes opened beside it ([`Rpc::open_programs`]).
888	    pub(crate) async fn release(&self) {
889	        let lanes = self.take_lanes();
890	        for snapshot in std::iter::once(self.snapshot).chain(lanes) {
891	            self.call(&Release { snapshot }).await.ok();
892	        }
893	    }
894	
895	    /// Releases the snapshots of the lanes opened beside this one ([`Rpc::open_programs`]) and keeps this one's: what
896	    /// they hold (each lane's program and its checker's caches) is freed before the work that follows the lanes. Each is
897	    /// released once, here or by [`Rpc::release`], never by both. Nothing may ask a lane after.
898	    pub(crate) async fn release_lanes(&self) {
899	        for snapshot in self.take_lanes() {
900	            self.call(&Release { snapshot }).await.ok();
901	        }
902	    }
903	
904	    /// The lanes' snapshots not yet released, which are then no longer this one's to release.
905	    fn take_lanes(&self) -> Vec<u64> {
906	        std::mem::take(&mut *self.others.lock().unwrap_or_else(std::sync::PoisonError::into_inner))
907	    }
908	
909	    /// The recorded calls as a JSON array, or `None` when recording was off.
910	    pub(crate) fn recording(&self) -> Option<Value> {
911	        let log = self.recording.as_ref()?.lock().ok()?;
912	        Some(Value::Array(log.clone()))
913	    }
914	
915	    /// Requests sent so far, by method.
916	    /// The requests inside a batch count under their own methods and in all as `inBatches`, and the batch once as
917	    /// `batchRequests`. It is a profile, not a count of round trips: a batch and its requests are both in it.
918	    pub(crate) fn calls(&self) -> BTreeMap<&'static str, u64> {
919	        self.calls.lock().map(|calls| calls.clone()).unwrap_or_default()
920	    }
921	
922	    /// One request, its answer as the JSON text it arrived as: [`decode`] parses it once, into the shape the caller
923	    /// expects. The parameters are written straight to the text the checker reads.
924	    async fn call(&self, params: &impl Request) -> Result<Box<RawValue>, CallError> {
925	        let method = params.method();
926	        if !params.frees_memory() {
927	            crate::heap::step()?;
928	        }
929	        if let Ok(mut calls) = self.calls.lock() {
930	            *calls.entry(method).or_default() += 1;
931	        }
932	        REQUESTS.try_with(|count| count.fetch_add(1, std::sync::atomic::Ordering::Relaxed)).ok();
933	        let params = serde_json::to_vec(params)
