729	    use std::time::Duration;
730	
731	    use caliper_docgen_core::pipeline::{PipelineOptions, extract};
732	    use caliper_docgen_core::types::semantic::{
733	        Delivery, Priority, SemanticOutcome, SemanticProvider, SemanticTarget, SharedPriority, SourceChange,
734	    };
735	    use camino::Utf8PathBuf;
736	    use std::sync::atomic::Ordering;
737	
738	    use super::{Checker, Job, OnDemand, OnDemandConfig, WARM_FILE, warm_source};
739	
740	    use super::{INTERACTIVE_STREAK, Queue, RSS_CHECK_EVERY, Upkeep};
741	
742	    /// A story asked while background requests wait is answered before them. The worker is held until all four are
743	    /// queued ([`OnDemand::hold`]); it then files every queued job before it picks one, so the order does not depend on
744	    /// how fast the test thread queues them. The answers arrive in the order the one worker gives them.
745	    #[test]
746	    fn a_story_asked_behind_queued_background_requests_is_answered_before_them() {
747	        let dir = tempfile::Builder::new().prefix("OnDemand").tempdir().unwrap();
748	        let root = Utf8PathBuf::from_path_buf(std::fs::canonicalize(dir.path()).unwrap()).unwrap();
749	        let fixtures = Utf8PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/project");
750	        for name in ["Button.tsx", "tsconfig.json"] {
751	            std::fs::copy(fixtures.join(name), root.join(name)).unwrap();
752	        }
753	        let output = extract(&PipelineOptions { src_dirs: vec![root.clone()], ..PipelineOptions::default() });
754	        let target = |name: &str| crate::targets_of(&output).into_iter().find(|t| t.display_name == name).unwrap();
755	        let checker = OnDemand::new(OnDemandConfig::new(root.clone()));
756	        let (sender, answered) = std::sync::mpsc::channel();
757	        let queue = |name: &'static str, priority: Priority| {
758	            let sender = sender.clone();
759	            let delivery = Delivery::new(move |outcome| {
760	                sender.send((name, outcome)).ok();
761	            });
762	            checker.request_at(vec![target(name)], SharedPriority::new(priority), delivery);
763	        };
764	
765	        let release = checker.hold();
766	        for _ in 0..3 {
767	            queue("Button", Priority::Background);
768	        }
769	        queue("Other", Priority::Interactive);
770	        release.send(()).unwrap();
771	
772	        let order: Vec<&str> = (0..4)
773	            .map(|_| {
774	                let (name, outcome) = answered.recv_timeout(Duration::from_secs(60)).expect("an answer");
775	                let outcome = outcome.expect("the checker answered");
776	                assert_eq!(outcome.components.len(), 1, "{name}: {:?}", outcome.diagnostics);
777	                name
778	            })
779	            .collect();
780	
781	        assert_eq!(order, ["Other", "Button", "Button", "Button"]);
782	    }
783	
784	    /// A project whose `Button` takes props from the package `dep` it depends on, every file written an hour ago (a
785	    /// stamp taken within two seconds of an edit cannot tell it from the next).
786	    struct Warmed {
787	        _dir: tempfile::TempDir,
788	        root: Utf8PathBuf,
789	        config: OnDemandConfig,
790	    }
791	
792	    const BUTTON: &str = "import type { DepProps } from \"dep\";\nexport function Button(props: DepProps & { label: string }) { return null; }\n";
793	
794	    impl Warmed {
795	        fn new() -> Self {
796	            let dir = tempfile::Builder::new().prefix("Warmed").tempdir().unwrap();
797	            let root = Utf8PathBuf::from_path_buf(std::fs::canonicalize(dir.path()).unwrap()).unwrap();
798	            let fixture = Utf8PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/project/tsconfig.json");
799	            std::fs::copy(fixture, root.join("tsconfig.json")).unwrap();
800	            std::fs::create_dir_all(root.join("node_modules/dep")).unwrap();
801	            let mut config = OnDemandConfig::new(root.clone());
802	            config.tsconfig = Some(root.join("tsconfig.json"));
803	            let project = Self { _dir: dir, root, config };
804	            project.write(
805	                "package.json",
806	                r#"{ "name": "app", "dependencies": { "dep": "1.0.0", "@types/dep": "1.0.0" } }"#,
807	            );
808	            project.write("node_modules/dep/package.json", r#"{ "name": "dep", "types": "index.d.ts" }"#);
809	            project.write("node_modules/dep/index.d.ts", "export interface DepProps { fromDep?: string }\n");
810	            project.write("Button.tsx", BUTTON);
811	            project
812	        }
813	
814	        /// Writes `text` to `name`, modified an hour ago, or half an hour ago when `later`.
815	        fn write_at(&self, name: &str, text: &str, later: bool) {
816	            std::fs::write(self.root.join(name), text).unwrap();
817	            let file = std::fs::File::options().write(true).open(self.root.join(name)).unwrap();
818	            let ago = Duration::from_secs(if later { 1800 } else { 3600 });
819	            file.set_modified(std::time::SystemTime::now() - ago).unwrap();
820	        }
821	
822	        fn write(&self, name: &str, text: &str) {
823	            self.write_at(name, text, false);
824	        }
825	
826	        fn button(&self) -> SemanticTarget {
827	            let output = extract(&PipelineOptions { src_dirs: vec![self.root.clone()], ..PipelineOptions::default() });
828	            crate::targets_of(&output).into_iter().find(|target| target.display_name == "Button").unwrap()
829	        }
830	    }
831	
832	    fn props(outcome: &SemanticOutcome) -> Vec<&str> {
833	        outcome.components.iter().flat_map(|component| &component.props).map(|prop| prop.name.as_str()).collect()
834	    }
835	
836	    fn current_thread() -> tokio::runtime::Runtime {
837	        tokio::runtime::Builder::new_current_thread().enable_all().build().unwrap()
838	    }
839	
840	    /// Whether the checker still holds `snapshot`: releasing one it does not hold fails, as releasing an unknown one does.
841	    fn holds(runtime: &tokio::runtime::Runtime, checker: &Checker, snapshot: u64) -> bool {
842	        let client = checker.backend.as_ref().unwrap().client();
843	        let params = serde_json::json!({ "snapshot": snapshot }).to_string().into_bytes();
844	        runtime.block_on(client.request_raw("release", params, Duration::from_secs(60))).is_ok()
845	    }
846	
847	    fn snapshot_of(checker: &Checker) -> u64 {
848	        checker.live.as_ref().unwrap().rpc.snapshot_id()
849	    }
850	
851	    /// The warm-up keeps a snapshot over the project's dependencies, its files stamped; the first request brings it up to
852	    /// date, re-rooted at its file and with the edit announced before it read again, instead of building one, and the
853	    /// warm-up's snapshot is released once replaced. The answer is a cold checker's. On the base the warm-up kept no
854	    /// snapshot, and the first request built one.
855	    #[test]
856	    fn the_first_request_after_a_warm_up_updates_the_warm_snapshot_and_releases_it() {
857	        let project = Warmed::new();
858	        let runtime = current_thread();
859	        let mut checker = Checker::default();
860	
861	        runtime.block_on(checker.take(&project.config, Job::Warm, &mut Queue::default()));
862	        let warm = checker.live.as_ref().expect("the warm-up keeps a snapshot");
863	        let stamped: Vec<String> = warm.stamps.as_ref().unwrap().keys().map(ToString::to_string).collect();
864	        let warm_snapshot = snapshot_of(&checker);
865	        assert_eq!(warm.roots, [project.root.join(WARM_FILE).to_string()]);
866	        assert!(stamped.contains(&project.root.join("node_modules/dep/index.d.ts").to_string()), "{stamped:?}");
867	        assert!(!stamped.iter().any(|file| file.ends_with(WARM_FILE)), "{stamped:?}");
868	        project.write("Button.tsx", &BUTTON.replace("label: string", "label: string; edited: number"));
869	        let changed = SourceChange::Files(vec![project.root.join("Button.tsx")]);
870	        runtime.block_on(checker.take(&project.config, Job::Changed(changed), &mut Queue::default()));
871	        let first = runtime.block_on(checker.answer(&project.config, vec![project.button()]));
872	
873	        assert_eq!(props(&first), ["fromDep", "label", "edited"], "{first:?}");
874	        assert_eq!(
875	            (checker.gauges.created.load(Ordering::Relaxed), checker.gauges.updated.load(Ordering::Relaxed)),
876	            (1, 1),
877	            "the warm-up built the one snapshot, which the first request brought up to date"
878	        );
879	        assert_eq!(checker.live.as_ref().unwrap().roots, [project.root.join("Button.tsx").to_string()]);
880	        assert_ne!(snapshot_of(&checker), warm_snapshot);
881	        assert!(!holds(&runtime, &checker, warm_snapshot), "the warm-up's snapshot is released once replaced");
882	        let mut cold = Checker::default();
883	        assert_eq!(runtime.block_on(cold.answer(&project.config, vec![project.button()])), first);
884	        for checker in [checker, cold] {
885	            runtime.block_on(checker.backend.unwrap().shutdown());
886	        }
887	    }
888	
889	    /// A dependency the warm-up read that changed with nobody telling the checker is read from the disk at the first
890	    /// request, with a warning that names it, and the warm-up's snapshot is released.
891	    #[test]
892	    fn a_dependency_changed_unannounced_after_a_warm_up_is_read_again_with_a_warning() {
893	        let project = Warmed::new();
894	        let runtime = current_thread();
895	        let mut checker = Checker::default();
896	
897	        runtime.block_on(checker.take(&project.config, Job::Warm, &mut Queue::default()));
898	        let warm_snapshot = snapshot_of(&checker);
899	        project.write_at("node_modules/dep/index.d.ts", "export interface DepProps { fromDep2?: string }\n", true);
